line = input("Convert: ")
number_text, source, _, target = line.split()
value = float(number_text)

lengths = ("m", "km", "cm", "mi", "ft", "in")
temperatures = ("C", "F", "K")

if source not in lengths and source not in temperatures:
    print(f"Unknown unit: {source}")
elif target not in lengths and target not in temperatures:
    print(f"Unknown unit: {target}")
elif (source in lengths) != (target in lengths):
    print(f"Cannot convert {source} to {target}")
elif source in lengths:
    # How many metres one of each unit is.
    if source == "km":
        source_size = 1000
    elif source == "cm":
        source_size = 0.01
    elif source == "mi":
        source_size = 1609.344
    elif source == "ft":
        source_size = 0.3048
    elif source == "in":
        source_size = 0.0254
    else:
        source_size = 1
    if target == "km":
        target_size = 1000
    elif target == "cm":
        target_size = 0.01
    elif target == "mi":
        target_size = 1609.344
    elif target == "ft":
        target_size = 0.3048
    elif target == "in":
        target_size = 0.0254
    else:
        target_size = 1
    result = value * source_size / target_size
    print(f"{value:g} {source} = {result:.2f} {target}")
else:
    # Temperatures go through Celsius.
    if source == "F":
        celsius = (value - 32) * 5 / 9
    elif source == "K":
        celsius = value - 273.15
    else:
        celsius = value
    if target == "F":
        result = celsius * 9 / 5 + 32
    elif target == "K":
        result = celsius + 273.15
    else:
        result = celsius
    print(f"{value:g} {source} = {result:.2f} {target}")
